SELECT COALESCE(SUM(liter), 0)        AS soldLiter,
       COALESCE(SUM(total_amount), 0) AS revenue
FROM tb_transaction
WHERE tank_id = #{tankId}
  AND tx_datetime >= #{startOfDay}

SELECT COALESCE(SUM(liter), 0)
FROM tb_transaction
WHERE tank_id = #{tankId}
  AND tx_datetime >= #{since}

SELECT DATE(MAX(tx_datetime))
FROM tb_transaction
WHERE tank_id = #{tankId}
  AND tx_datetime >= #{since}

mapper.delete:
DELETE FROM tb_transaction
WHERE tank_id = #{tankId}
  AND DATE(tx_datetime) = #{saleDate}
  AND input_type = 'EXCEL'

mapper.select:
SELECT COUNT(1)
FROM tb_transaction
WHERE tank_id = #{tankId}
  AND DATE(tx_datetime) = #{saleDate}
  AND input_type = 'EXCEL'

SELECT DATE_FORMAT(t.tx_datetime, '%Y-%m') AS period_key, tk.fuel_type AS fuel_type, COALESCE(SUM(t.liter), 0) AS total_liter FROM tb_transaction t JOIN tb_tank tk ON t.tank_id = tk.tank_id WHERE tk.fuel_type IN ('GASOLINE', 'DIESEL')
AND DATE(t.tx_datetime) >= #{startDate}
AND DATE(t.tx_datetime) <= #{endDate}
GROUP BY DATE_FORMAT(t.tx_datetime, '%Y-%m'), tk.fuel_type ORDER BY period_key ASC, tk.fuel_type ASC

SELECT DATE(t.tx_datetime) AS period_key, tk.fuel_type AS fuel_type, COALESCE(SUM(t.liter), 0) AS total_liter FROM tb_transaction t JOIN tb_tank tk ON t.tank_id = tk.tank_id WHERE tk.fuel_type IN ('GASOLINE', 'DIESEL')
AND DATE(t.tx_datetime) >= #{startDate}
AND DATE(t.tx_datetime) <= #{endDate}
GROUP BY DATE(t.tx_datetime), tk.fuel_type ORDER BY period_key ASC, tk.fuel_type ASC

SELECT DATE_SUB(DATE(t.tx_datetime), INTERVAL WEEKDAY(t.tx_datetime) DAY) AS period_key, tk.fuel_type AS fuel_type, COALESCE(SUM(t.liter), 0) AS total_liter FROM tb_transaction t JOIN tb_tank tk ON t.tank_id = tk.tank_id WHERE tk.fuel_type IN ('GASOLINE', 'DIESEL')
AND DATE(t.tx_datetime) >= #{startDate}
AND DATE(t.tx_datetime) <= #{endDate}
GROUP BY DATE_SUB(DATE(t.tx_datetime), INTERVAL WEEKDAY(t.tx_datetime) DAY), tk.fuel_type ORDER BY period_key ASC, tk.fuel_type ASC

SELECT sub.dow AS dow, sub.fuel_type AS fuel_type, AVG(sub.daily_total) AS avg_liter FROM ( SELECT WEEKDAY(t.tx_datetime) AS dow, tk.fuel_type AS fuel_type, COALESCE(SUM(t.liter), 0) AS daily_total FROM tb_transaction t JOIN tb_tank tk ON t.tank_id = tk.tank_id WHERE tk.fuel_type IN ('GASOLINE', 'DIESEL')
AND DATE(t.tx_datetime) >= #{startDate}
AND DATE(t.tx_datetime) <= #{endDate}
GROUP BY DATE(t.tx_datetime), WEEKDAY(t.tx_datetime), tk.fuel_type ) sub GROUP BY sub.dow, sub.fuel_type ORDER BY sub.dow ASC, sub.fuel_type ASC

